/* CLICQUE: autonomous AI contestants (readable copy). Already built into clicque.html and www/index.html. */

/* ===== cast.js ===== */
/* ---------- autonomous cast: profiles, relationships, memory, alliances, rumours, feed, private messages ---------- */
/* ---------- LOCKS: flip a value to true/false to lock/unlock a feature instantly ---------- */
const LOCK={monitor:false,   // the whole bottom stat monitor ("The Show")
  messages:true,             // Messages tab (private chats with AI players)
  alliances:true,            // Alliances tab
  location:true};            // where contestants are from (hidden in profiles and in AI dialogue)
const TK=['conf','comp','stab','soc','strat','trust','ego','temp','ctol','aware','risk'];
const rndi=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
const clamp=(x,a=0,b=100)=>Math.max(a,Math.min(b,x));
const ARCH=[
['manip','sharp',[70,75,70,80,92,25,65,30,60,85,60],'dry and calculating',20],
['loud','drama',[85,95,40,55,45,60,85,80,90,45,75],'trash-talking',70],
['social','joker',[70,45,65,95,60,70,50,35,40,90,40],'friendly and gossipy',60],
['quiet','quiet',[55,60,85,60,90,65,35,15,35,85,35],'deadpan',5],
['emo','drama',[50,55,30,70,40,80,60,75,45,60,45],'warm and self-deprecating',40],
['wild','joker',[75,60,30,50,40,35,60,70,70,35,95],'chaotic',65],
['loyal','loyal',[60,50,80,65,50,92,40,30,40,65,25],'wholesome',25],
['joker','joker',[75,40,70,70,45,55,55,30,45,60,55],'teasing',75],
['under','chill',[35,70,55,50,70,60,30,35,40,70,50],'self-deprecating',30]];
const STR={manip:['reads votes','patient planner'],loud:['wins challenges','intimidates'],social:['knows everyone','connector'],quiet:['remembers everything','unreadable'],emo:['forms deep bonds','honest'],wild:['unpredictable','fearless'],loyal:['protects friends','reliable'],joker:['defuses tension','likable'],under:['underestimated','hungry']};
const WKN={manip:['trusts no one','overthinks'],loud:['bad loser','burns bridges'],social:['spreads too thin','gossips'],quiet:['too passive','slow to act'],emo:['takes betrayal personally','impulsive'],wild:['unreliable','creates enemies'],loyal:['blind to betrayal','too trusting'],joker:['not taken seriously','avoids conflict'],under:['insecure','overcompensates']};
function mkProf(i){const a=ARCH[i%ARCH.length],t={};TK.forEach((k,j)=>{t[k]=clamp(a[2][j]+rndi(-12,12),5,98)});return{ar:a[0],pers:a[1],t,hu:a[3],sl:clamp(a[4]+rndi(-12,12),0,95),str:STR[a[0]],wk:WKN[a[0]]}}
/* relationships: ordered pair a -> b, 0..100 */
const REL=(a,b)=>{G.rel[a]=G.rel[a]||{};return G.rel[a][b]||(G.rel[a][b]={tr:50,fr:30,re:45,ri:5,su:15,rs:0,aa:40})};
const MEMB=id=>{const p=P(id);return p&&p.mem};
function bump(a,b,k,v,why){if(a===b||a===-1||b===-1)return;const r=REL(a,b);r[k]=clamp(r[k]+v);const m=MEMB(a);if(m&&why&&Math.abs(v)>=8){m.ev.push({r:G.n,k,v,b,why});if(m.ev.length>40)m.ev.shift()}}
const affOf=(a,b)=>{const r=REL(a,b);return Math.max(-3,Math.min(3,((r.tr-50)+(r.fr-30)-r.ri-(r.su-15)-r.rs)/30))};
function relInit(){G.P.forEach(a=>{if(isH(a))return;G.rel[a.id]={};const tw=(a.prof.t.trust-50)/6;G.P.forEach(b=>{if(a===b)return;G.rel[a.id][b.id]={tr:clamp(50+tw+rndi(-14,14)),fr:clamp(28+rndi(-10,12)),re:clamp(45+rndi(-14,14)),ri:clamp(4+rndi(0,8)),su:clamp(14+rndi(-6,12)),rs:0,aa:clamp(40+rndi(-15,15))}})});
G.rels.forEach(x=>{const rv=x.type==='rivals';[[x.a,x.b],[x.b,x.a]].forEach(([p,q])=>{const r=REL(p.id,q.id);if(rv){r.ri=clamp(r.ri+45);r.rs=clamp(r.rs+15);r.tr=clamp(r.tr-20)}else{r.fr=clamp(r.fr+32);r.tr=clamp(r.tr+22)}})})}
function castInit(){G.rel={};G.al=[];G.feed=[];G.dms={};G.prop={};G.betray={};G.hist=[];G.pubRel={};G.celeb=[];G.cfb=[];G.evq=[];G.unread=0;G.dmUnread=0;G.tab='feed';G.showOpen=false;G.dmOpen=null;
G.P.forEach(b=>{if(isH(b))return;b.mem={against:{},votedFor:{},betrayedBy:{},saved:{},ev:[],embar:{}};b.mood={m:'calm',l:0,why:''};b.rum={};b.cd={};b.surv=0});
relInit();restoreCast();G.P.forEach(b=>{if(!isH(b))b.goal=pickGoal(b)})}
function castWarm(){for(let i=0;i<6;i++)castTick();G.evq=[];renderShowBar()}
/* alliances */
const allianceOf=id=>G.al.find(x=>!x.broken&&x.m.includes(id));
const ally=(a,b)=>{const x=allianceOf(a);return !!x&&x.m.includes(b)};
function formAlliance(a,b,pub){let x=allianceOf(a)||allianceOf(b);if(x){if(!x.m.includes(a))x.m.push(a);if(!x.m.includes(b))x.m.push(b)}else{x={id:G.al.length+1,m:[a,b],r:G.n,broken:false,pub:!!pub,found:false,bf:false,disc:new Set()};G.al.push(x)}
bump(a,b,'tr',12,'alliance');bump(b,a,'tr',12,'alliance');bump(a,b,'aa',10);bump(b,a,'aa',10);bump(a,b,'fr',8);bump(b,a,'fr',8);x.m.forEach(i=>{if(isH(P(i)))x.disc.add(i)});return x}
function acceptProb(b,a){const r=REL(b.id,a.id),pt=b.prof?b.prof.t:{soc:50};let p=(r.tr*.4+r.fr*.25+r.re*.1+r.aa*.25)/100+(pt.soc-50)/200-r.su/200;if(allianceOf(b.id)&&!ally(b.id,a.id))p-=.1;return clamp(p,.05,.92)/1}
function breakAlly(v,c){const x=allianceOf(v.id);if(!x)return;x.m=x.m.filter(i=>i!==v.id);if(x.m.length<2)x.broken=true;x.bf=true;
bump(c.id,v.id,'tr',-45,'betrayal');bump(c.id,v.id,'rs',40);bump(c.id,v.id,'ri',20);if(c.mem)c.mem.betrayedBy[v.id]=(c.mem.betrayedBy[v.id]||0)+1;
if(!isH(c)){setEmo(c,c.prof.t.temp>55?'angry':'betrayed',75,'betrayed',v.id);c.goal={k:'revenge',t:v.id}}delete G.betray[v.id];G.pubRel[v.id+'-'+c.id]=-1;story(`Round ${G.n}: ${v.name} betrayed ${c.name} and the alliance broke`);feed('betray',v,c,true);if(x.broken)feed('split',v,c,true);G.cfb.push({a:c.id,b:v.id})}
function setEmo(b,m,l,why,tg){if(!b.mood)return;if(l>=b.mood.l||m===b.mood.m)b.mood={m,l:Math.min(100,l),why,tg:tg===undefined?null:tg}}
const story=x=>{G.story.push(x);if(G.story.length>30)G.story.shift()};
function storyChat(){G.P.forEach(b=>{if(!isH(b)&&b.alive)b.silent=(G.rmsgs[b.id]>0)?0:(b.silent||0)+1});const top=Object.entries(G.racc||{}).sort((a,b)=>b[1]-a[1])[0];if(top&&top[1]>=2)story(`Round ${G.n} chat: ${pn(top[0])} was accused ${top[1]} times`);G.racc={}}
/* feed and message badges */
function feed(k,a,b,drama,extra){if((k==='ally'||k==='split')&&LOCK.alliances)return;if(k==='dm'&&LOCK.messages)return;G.feed.unshift({r:G.n,k,a:a?a.id:null,b:b?b.id:null,d:!!drama,...(extra||{})});if(G.feed.length>80)G.feed.pop();if(!G.showOpen||G.tab!=='feed')G.unread++;renderShowBar();if(G.showOpen&&G.tab==='feed')renderShow()}
/* votes -> memory, relationships, betrayals, emotions */
function afterVotes(votes,secret,mode,picks){const w=picks>1?.5:1,rc={};
votes.forEach(x=>{const v=x.v,c=x.c;if(v.id===-1)return;G.hist.push({r:G.n,v:v.id,c:c.id,s:!!secret,m:mode,w});
if(mode==='out'){if(!secret){if(c.mem)c.mem.against[v.id]=(c.mem.against[v.id]||0)+w;rc[c.id]=(rc[c.id]||0)+w;
bump(c.id,v.id,'rs',12*w,'vote');bump(c.id,v.id,'tr',-10*w);bump(c.id,v.id,'ri',6*w);if(ally(v.id,c.id)&&picks===1)breakAlly(v,c);
G.P.forEach(o=>{if(o!==v&&o!==c&&!isH(o)&&o.alive&&REL(o.id,c.id).fr>=60)bump(o.id,v.id,'rs',3*w)})}
if(v.mem)v.mem.votedFor[c.id]=(v.mem.votedFor[c.id]||0)+w}
else if(mode==='save'&&!secret){bump(c.id,v.id,'tr',10,'saved');bump(c.id,v.id,'fr',7);if(v.mem)v.mem.saved[c.id]=(v.mem.saved[c.id]||0)+1}});
if(mode==='out'&&!secret)G.P.forEach(b=>{if(!isH(b)&&b.alive&&rc[b.id]>=2)setEmo(b,rc[b.id]>=3?'fear':(b.prof.t.temp>60?'angry':'anxious'),45+10*rc[b.id],'votes')})}
function afterElim(p){const hv=G.hist.filter(h=>h.r===G.n&&!h.s&&h.m==='out'&&h.v!==-1),cnt={};hv.forEach(h=>{cnt[h.c]=(cnt[h.c]||0)+(h.w||1)});
G.P.forEach(b=>{if(isH(b)||!b.alive)return;const r=REL(b.id,p.id),mine=hv.filter(h=>h.v===b.id).map(h=>h.c);
if(r.fr>=55)setEmo(b,'sad',60,'friend out',p.id);else if(ally(b.id,p.id))setEmo(b,'disappointed',50,'ally out',p.id);
if(r.ri>=40||r.rs>=40)G.celeb.push({a:b.id,b:p.id});
if(mine.includes(p.id)&&(r.rs>=25||r.ri>=20||r.su>=40))setEmo(b,'happy',48,'plan worked',p.id);
else{const sv=mine.find(c2=>P(c2).alive&&REL(b.id,c2).rs>=30);if(sv!==undefined)setEmo(b,'frustrated',52,'target survived',sv)}
if((cnt[b.id]||0)>=2)setEmo(b,'relieved',58,'survived the votes');
if(r.fr>=60&&b.prof.t.temp>=50&&Math.random()<.5){const v0=hv.find(h=>h.c===p.id);if(v0&&v0.v!==b.id&&P(v0.v).alive)b.goal={k:'revenge',t:v0.v}}
if(A().length<=3&&b.prof.t.comp>50)b.goal={k:'win',t:null}});
if(p.mood)setEmo(p,p.prof&&p.prof.t.ego>60?'embarrassed':'sad',55,'eliminated');
G.al.forEach(x=>{x.m=x.m.filter(i=>i!==p.id);if(x.m.length<2)x.broken=true});delete G.betray[p.id];Object.keys(G.betray).forEach(k=>{if(G.betray[k]===p.id)delete G.betray[k]});story(`Round ${G.n}: ${p.name} was eliminated`);feed('out',p,null,false);saveCast()}
function roundTick(){G.P.forEach(b=>{if(isH(b)||!b.alive)return;b.mood.l=Math.round(b.mood.l*.6);if(b.mood.l<12)b.mood.m='calm';b.cd={};if(G.n>1)b.surv++;
Object.values(G.rel[b.id]||{}).forEach(r=>{r.rs=Math.round(r.rs*.94)});
if(G.n===1&&['loud','joker','wild','social'].includes(b.prof.ar))setEmo(b,'excited',45,'new game');
{const sp=G.P.filter(x=>x!==b&&x.alive).sort((p,q)=>REL(b.id,q.id).su-REL(b.id,p.id).su)[0];if(sp&&REL(b.id,sp.id).su>=60)setEmo(b,'suspicious',42,'suspects someone',sp.id)}
if(A().length<=4&&b.prof.t.comp>60)setEmo(b,'excited',48,'near the end');
if((b.silent||0)>=2&&b.prof.t.conf<60)setEmo(b,'bored',40,'nothing happening');
if(b.surv>=2&&b.prof.t.ego>50&&b.mood.m==='calm')setEmo(b,'confident',38,'still standing');
const al=allianceOf(b.id),maxf=Math.max(0,...G.P.filter(x=>x!==b&&x.alive).map(x=>REL(b.id,x.id).fr));
if(!al&&maxf<35&&G.n>1)setEmo(b,'anxious',48,'isolated');
if(b.surv>=3&&b.prof.t.ego>55&&!G.hist.some(h=>h.c===b.id&&!h.s&&h.m==='out'))setEmo(b,'proud',55,'streak');
const h=G.P.find(p=>p.hum);if(h&&h.alive&&REL(b.id,h.id).fr>=55&&b.prof.t.ego>60&&Math.random()<.3)setEmo(b,'jealous',50,'player popular');
if(al&&G.n>=3&&G.betray[b.id]===undefined){const x=al.m.filter(i=>i!==b.id&&P(i).alive).sort((p,q)=>REL(b.id,q).re-REL(b.id,p).re)[0];
if(x!==undefined){const bt=(100-b.prof.t.trust)/100*.5+b.prof.t.risk/100*.3+b.prof.t.strat/100*.2-REL(b.id,x).fr/100*.45;if(bt>.42&&Math.random()<.5)G.betray[b.id]=x}}})}
/* autonomous activity: one decision cycle */
function castTick(){const bs=A().filter(p=>!isH(p));if(bs.length<2)return;const R=Math.random,h=G.P.find(p=>p.hum);
if(G.cfb.length){const x=G.cfb.shift(),a=P(x.a),b=P(x.b);if(a.alive&&b.alive&&!isH(a)){G.evq.push({s:a,kind:'ev',evk:'cfb',tg:b,fast:1});return}}
if(G.celeb.length&&R()<.6){const x=G.celeb.shift(),a=P(x.a);if(a.alive&&!isH(a)){G.evq.push({s:a,kind:'ev',evk:'cel',tg:P(x.b),about:P(x.b),fast:1});return}}
const w=bs.map(b=>1+(b.prof.t.soc+b.prof.t.conf+b.prof.t.ego)/100+b.mood.l/50);let r=R()*w.reduce((s,x)=>s+x,0),a=bs[0];for(let i=0;i<bs.length;i++){r-=w[i];if(r<=0){a=bs[i];break}}
const others=A().filter(p=>p!==a),cd=a.cd;
const g=others.filter(c=>(a.mem.against[c.id]||0)>=1&&REL(a.id,c.id).rs>=42).sort((p,q)=>REL(a.id,q.id).rs-REL(a.id,p.id).rs)[0];
if(g&&!cd.cf&&R()<(a.prof.t.temp+a.prof.t.ctol)/180){cd.cf=1;G.evq.push({s:a,kind:'ev',evk:'cf',tg:g,k:Math.round(a.mem.against[g.id]),fast:0});return}
if(a.mood.l>=55&&!cd.em&&R()<.35){const mm={angry:'ang',anxious:'anx',proud:'prd',jealous:'jea',hurt:'hur'}[a.mood.m];if(mm){cd.em=1;const tg=[...others].sort((p,q)=>REL(a.id,q.id).rs-REL(a.id,p.id).rs)[0];G.evq.push({s:a,kind:'ev',evk:mm,tg,fast:0});return}}
if(h&&h.alive&&!LOCK.messages&&!cd.dm&&R()<.28){const q=REL(a.id,h.id),kind=q.tr>=55&&q.fr>=40&&!ally(a.id,h.id)&&!G.prop[a.id]?'prop':q.rs>=40?'cf':q.fr>=45?(R()<.5?'gos':'adv'):null;if(kind){cd.dm=1;dmFrom(a,kind);return}}
if(!cd.al&&R()<(a.prof.t.soc+a.prof.t.strat)/260){const b=others.filter(c=>!isH(c)&&!ally(a.id,c.id)).sort((p,q)=>(REL(a.id,q.id).tr+REL(a.id,q.id).aa)-(REL(a.id,p.id).tr+REL(a.id,p.id).aa))[0];
if(b&&REL(a.id,b.id).tr>=56){cd.al=1;if(R()<acceptProb(b,a)){formAlliance(a.id,b.id,false);if(R()<.18)feed('ally',a,b,false)}else bump(a.id,b.id,'fr',-3);return}}
if(!cd.go&&R()<.3){const f=others.find(c=>!isH(c)&&REL(a.id,c.id).fr>=48&&REL(c.id,a.id).tr>=40),c=others.filter(x=>x!==f&&REL(a.id,x.id).su>=42).sort((p,q)=>REL(a.id,q.id).su-REL(a.id,p.id).su)[0];
if(f&&c){cd.go=1;const cf=REL(f.id,a.id).tr/100*24;f.rum[c.id]=Math.min(60,(f.rum[c.id]||0)+cf);bump(f.id,c.id,'su',cf*.5);if(R()<.3)feed('rumor',a,c,false);return}}
const al=allianceOf(a.id);if(al&&!cd.pl&&R()<.35){const m=al.m.map(P).find(x=>x!==a&&x.alive&&!isH(x));if(m){const cs=others.filter(c=>c!==m&&!al.m.includes(c.id));if(cs.length){const d=decide(a,cs,'out');cd.pl=1;G.intent[m.id+'out']={c:d.c,f:d.f};return}}}
const ap=others.find(c=>!isH(c)&&(a.mem.votedFor[c.id]||0)>=1&&REL(c.id,a.id).rs>=35&&a.prof.t.stab>45&&a.prof.t.trust>40);if(ap&&!cd.ap&&R()<.18){cd.ap=1;G.evq.push({s:a,kind:'ev',evk:'apo',tg:ap,fast:0})}}
function evEffects(m){const a=m.s,c=m.tg;if(!c)return;
if(m.evk==='cf'||m.evk==='cfb')story(`Round ${G.n}: ${a.name} confronted ${c.name} in public`);
if(m.evk==='cf'||m.evk==='cfb'){if(c.mood&&c.prof&&c.prof.t.ego>55)setEmo(c,'embarrassed',45,'called out',a.id);if(c.mem)c.mem.embar[a.id]=(c.mem.embar[a.id]||0)+1}
if(m.evk==='cf'){bump(c.id,a.id,'su',6);bump(c.id,a.id,'rs',5);bump(a.id,c.id,'rs',-6);G.pubRel[a.id+'-'+c.id]=-1;feed('conf',a,c,(m.k||0)>=2)}
if(m.evk==='cfb'){bump(a.id,c.id,'rs',-8);G.pubRel[a.id+'-'+c.id]=-1;feed('conf',a,c,true)}
if(m.evk==='apo'&&c.prof){bump(c.id,a.id,'rs',-10);const fg=Math.random()<(c.prof.t.trust+(100-c.prof.t.ego))/200;G.evq.push({s:c,kind:'ev',evk:fg?'frg':'rfs',tg:a,fast:1});if(fg){bump(c.id,a.id,'rs',-25);bump(c.id,a.id,'tr',10);G.pubRel[a.id+'-'+c.id]=1}feed('apo',a,c,false)}}
/* private messages with the player */
const HP=()=>G.P.find(p=>p.hum);
function dmFrom(a,kind){const h=HP();let about=null;if(kind==='gos'){about=G.P.filter(x=>x!==a&&x!==h&&x.alive&&REL(a.id,x.id).su>=30).sort((p,q)=>REL(a.id,q.id).su-REL(a.id,p.id).su)[0];if(!about)kind='adv'}
const txt=fb(kind,{n:h.name,a:about?about.name:'',k:Math.max(1,Math.round(a.mem.against[h.id]||1))});
(G.dms[a.id]=G.dms[a.id]||[]).push({f:'b',t:txt});G.dmUnread++;if(kind==='prop')G.prop[a.id]={type:'ally'};feed('dm',a,null,kind==='prop');
if(G.showOpen&&G.tab==='dms'&&!(q('dmi')&&q('dmi').value))renderShow()}
const POS=/\b(yes|yeah|deal|ally|alliance|sure|ok|okay|in)\b|sí|oui|\bsim\b|\bja\b|aliad|alli[eé]|alian|bündnis|联盟|同意|好/i,NEG=/\b(no|nah|never|nope)\b|\bnon\b|não|nein|不要/i,ALW=/ally|alliance|aliad|alli[eé]|alian|bündnis|联盟|team up|together/i;
function dmDecide(b,text){const h=HP(),r=REL(b.id,h.id),pend=G.prop[b.id],pos=POS.test(text),neg=NEG.test(text);
if(r.rs>55||r.su>70){bump(b.id,h.id,'fr',-2);return{kind:'dmc',desc:'cold, not in the mood to talk'}}
if(pend&&pend.type==='ally'){G.prop[b.id]=null;if(pos&&!neg&&r.tr>=45){formAlliance(b.id,h.id,false);bump(b.id,h.id,'tr',10,'deal');bump(b.id,h.id,'fr',8);return{kind:'dmok',desc:'accept the alliance'}}bump(b.id,h.id,'fr',-4);return{kind:'dmno',desc:'decline politely, undecided'}}
if(ALW.test(text)&&!ally(b.id,h.id)){if(Math.random()<acceptProb(b,h)){formAlliance(b.id,h.id,false);return{kind:'dmok',desc:'accept the alliance'}}return{kind:'dmno',desc:'decline politely, undecided'}}
bump(b.id,h.id,'fr',2);bump(b.id,h.id,'tr',1);return{kind:'dmn',desc:'neutral and curious'}}
async function aiDM(b,text,outcome){const sm=await getSample();if(!sm||!CFG.aiChat||G.aiBackoff>Date.now())return null;const h=HP(),lang=['English','Spanish','French','Portuguese','German','Simplified Chinese'][LI()];
try{const r=await sm.json(`You are ${b.name} (${b.bio.age}, ${b.bio.job}${LOCK.location?'':' from '+b.bio.city}), a contestant in a reality-show elimination game. Language: ${lang}. Voice: ${b.prof.hu}; slang level ${b.prof.sl}/100; current mood: ${b.mood.m}. You are texting privately with ${h.name}, another contestant. Their message: "${String(text).slice(0,200)}". Your decision, already made and not to be changed: ${outcome}. Write ONE short text message (under 120 characters) in character. Do not invent game events or results. Return ONLY JSON {"text":"..."}`,{modelTier:'quick',cache:false});
return r&&typeof r.text==='string'&&r.text?mod(r.text).slice(0,140):null}catch(e){if(e&&e.code==='rate_limited')G.aiBackoff=Date.now()+60000;return null}}
async function dmSend(id){const i=q('dmi'),v=i&&i.value.trim();if(!v)return;i.value='';const b=P(id),gid=G.gid;(G.dms[id]=G.dms[id]||[]).push({f:'h',t:mod(v)});renderShow();
await wait(1200+Math.random()*1500);if(G.gid!==gid||!G.dms)return;const o=dmDecide(b,v);let line=await aiDM(b,v,o.desc);if(!line)line=fb(o.kind,{});G.dms[id].push({f:'b',t:line});renderShow()}
/* the show panel */
