/* contestant goals */
const GOALS={manip:'final3',loud:'win',social:'protect',quiet:'lowprofile',emo:'protect',wild:'chaos',loyal:'protect',joker:'lowprofile',under:'prove'};
function pickGoal(b){const k=GOALS[b.prof.ar]||'win',g={k,t:null};if(k==='protect'){const f=G.P.filter(x=>x!==b).sort((p,q)=>REL(b.id,q.id).fr-REL(b.id,p.id).fr)[0];g.t=f?f.id:null}return g}
function goalText(b){const g=b.goal;if(!g)return'';const n=g.t!==null&&g.t!==undefined?pn(g.t):'';return({win:'wants to win the whole thing',final3:'wants to reach the final three by planning ahead',protect:'wants to protect '+(n||'their closest friend'),revenge:'wants revenge on '+n,lowprofile:'wants to stay under the radar and survive',prove:'wants to prove everyone who underestimated them wrong',chaos:'follows impulse and likes to surprise people'})[g.k]||''}
function competitor(s){const c=A().filter(p=>p!==s&&!ally(s.id,p.id));if(!c.length)return null;const sc=p=>REL(s.id,p.id).re*((p.prof?p.prof.t.comp:60)/100)+(p.hum?8:0);return c.sort((a,b)=>sc(b)-sc(a))[0]}
/* reactions to game events: only contestants with a reason to react, 1 to 3 short lines */
const exposure=b=>(G.acc[b.id]||0)*2+Object.values(b.mem.against).reduce((s,x)=>s+x,0)*.5+b.mood.l/30+(['anxious','fear','nervous'].includes(b.mood.m)?2:0);
const qrLine=(pool,n)=>{const a=QR[pool];return rnd(a[LI()]||a[0]).split('{n}').join(n||'')};
function reactions(type,d){const out=[],used=new Set(),bs=A().filter(p=>!isH(p)&&p!==d),R=Math.random;
const add=(s,pool,tg)=>{if(!s||used.has(s.id)||out.length>=3)return;const x=qrLine(pool,tg?tg.name:'');if(dupe(x))return;used.add(s.id);out.push({s,text:x});G.log.push({n:s.name,t:x});G.said.add(norm(x))};
if(type==='theme'){const c=[...bs].sort((a,b)=>exposure(b)-exposure(a));if(c.length){add(c[0],exposure(c[0])>3?'nervous':'theme');if(c.length>1&&R()<.6)add(c[1],'theme')}}
else if(type==='eliminated'){bs.forEach(b=>{const r=REL(b.id,d.id);if(r.fr>=55)add(b,'sad',d);else if(r.ri>=40||r.rs>=40)add(b,'cel',d)});if(out.length<2){const o=bs.filter(x=>!used.has(x.id));if(o.length)add(rnd(o),'shock',d)}}
else if(type==='revived'){bs.forEach(b=>{const r=REL(b.id,d.id);if(r.fr>=50)add(b,'glad',d);else if(r.ri>=40||r.rs>=40)add(b,'mad',d)});if(!out.length&&bs.length)add(rnd(bs),'shock',d)}
else if(type==='final'){const all=G.P.filter(p=>!isH(p));if(all.length)add(rnd(all),'final')}
return out}
const rxHTML=a=>a&&a.length?`<div class="rxs">${a.map(x=>`<div>${x.s.emo} <b>${esc(x.s.name)}</b> “${esc(x.text)}”</div>`).join('')}</div>`:'';
/* game event system: one entry point; it updates emotions and memory, then returns reactions to show */
function gameEvent(type,d){
if(type==='votes')afterVotes(d.votes,d.secret,d.mode,d.picks);
else if(type==='eliminated')afterElim(d);
else if(type==='round_start')roundTick();
else if(type==='nominated')d.forEach(n=>{if(!isH(n)&&n.alive)setEmo(n,'nervous',55,'nominated')});
else if(type==='revived'){G.P.forEach(b=>{if(isH(b)||!b.alive||b===d)return;const r=REL(b.id,d.id);if(r.fr>=50)setEmo(b,'happy',55,'friend is back',d.id);else if(r.ri>=40||r.rs>=40)setEmo(b,'frustrated',45,'rival is back',d.id)})}
return(type==='theme'||type==='eliminated'||type==='revived'||type==='final')?reactions(type,d):[]}
/* persistence: the cast and its memories survive between games */
const savedCast=()=>{try{return JSON.parse(localStorage.getItem('clicque_cast')||'null')}catch(e){return null}};
function castNames(){const sc=CFG.keepCast?savedCast():null,bots=sc&&sc.bots?sc.bots.filter(b=>b.n!==CFG.name):[];if(!bots.length)return{nm:genNames(10),em:shuffle(EMO)};
const nm=bots.map(b=>b.n),em=bots.map(b=>typeof b.e==='string'&&EMO.includes(b.e)?b.e:null),more=genNames(14).filter(n=>!nm.includes(n)),fe=EMO.filter(e=>!em.includes(e));for(let i=0;i<em.length;i++)if(em[i]===null)em[i]=fe.length?fe.shift():rnd(EMO);while(nm.length<10)nm.push(more.shift());while(em.length<10)em.push(fe.length?fe.shift():rnd(EMO));return{nm:nm.slice(0,10),em:em.slice(0,10)}}
function saveCast(){if(!CFG.keepCast||!G||!G.rel)return;try{const nm=id=>(G.P.find(p=>p.id==id)||{}).name,mk=o=>{const r={};Object.keys(o||{}).forEach(k=>{const n=nm(k);if(n)r[n]=o[k]});return r};
const bots=G.P.filter(p=>!isH(p)).map(b=>({n:b.name,e:b.emo,pr:b.prof,bio:{age:b.bio.age,job:b.bio.job,city:b.bio.city,quirk:b.bio.quirk},m:{ag:mk(b.mem.against),vf:mk(b.mem.votedFor),bb:mk(b.mem.betrayedBy),sv:mk(b.mem.saved)},rel:mk(G.rel[b.id])}));
localStorage.setItem('clicque_cast',JSON.stringify({h:(HP()||{}).name,bots}))}catch(e){}}
function restoreCast(){const sc=CFG.keepCast?savedCast():null;if(!sc||!sc.bots)return;const id=n=>{const p=G.P.find(x=>x.name===n);return p?p.id:null},back=(o,f)=>{const r={};Object.keys(o||{}).forEach(n=>{const i=id(n);if(i!==null)r[i]=f?f(o[n]):o[n]});return r};
G.P.forEach(b=>{if(isH(b))return;const s=sc.bots.find(x=>x.n===b.name);if(!s||!s.pr||!s.pr.t)return;b.prof=s.pr;b.pers=s.pr.pers;Object.assign(b.bio,{age:s.bio.age,job:s.bio.job,city:s.bio.city,quirk:s.bio.quirk});
b.mem.against=back(s.m.ag,v=>Math.floor(v*.7));b.mem.votedFor=back(s.m.vf,v=>Math.floor(v*.7));b.mem.betrayedBy=back(s.m.bb);b.mem.saved=back(s.m.sv,v=>Math.floor(v*.7));
Object.entries(s.rel||{}).forEach(([n,r])=>{const i=id(n);if(i===null||i===b.id)return;const cur=REL(b.id,i);cur.tr=Math.round(50+(r.tr-50)*.7);cur.aa=Math.round(40+((r.aa===undefined?40:r.aa)-40)*.7);cur.fr=Math.round(30+(r.fr-30)*.7);cur.re=Math.round(45+(r.re-45)*.7);cur.su=Math.round(15+(r.su-15)*.5);cur.ri=Math.round(r.ri*.8);cur.rs=Math.round(r.rs*.8)})})}

